CREATE TABLE therapeutic_groups ( 
     id_therapeutic_group SERIAL PRIMARY KEY, 
     name                 VARCHAR(200) NOT NULL 
 ); 
  
 CREATE TABLE family ( 
     id_family            SERIAL PRIMARY KEY, 
     name                 VARCHAR(300) NOT NULL, 
     potential_illness    TEXT, 
     id_therapeutic_group INTEGER NOT NULL REFERENCES therapeutic_groups(id_therapeutic_group) 
 ); 
  
 CREATE TABLE laboratory ( 
     id_laboratory SERIAL PRIMARY KEY, 
     name          VARCHAR(200) NOT NULL 
 ); 
  
 CREATE TABLE pharmaceutical_form ( 
     id_pharmaceutical_form SERIAL PRIMARY KEY, 
     name                   VARCHAR(200) NOT NULL 
 ); 
  
 CREATE TABLE posology ( 
     id_posology SERIAL PRIMARY KEY, 
     name        TEXT NOT NULL 
 ); 
  
 CREATE TABLE product_details ( 
     id_product             SERIAL PRIMARY KEY, 
     commercial_name        VARCHAR(200) NOT NULL, 
     generic_name           VARCHAR(200), 
     id_family              INTEGER REFERENCES family(id_family), 
     action_mechanism       TEXT, 
     id_laboratory          INTEGER REFERENCES laboratory(id_laboratory), 
     concentration          VARCHAR(50), 
     id_pharmaceutical_form INTEGER REFERENCES pharmaceutical_form(id_pharmaceutical_form), 
     id_posology            INTEGER REFERENCES posology(id_posology), 
     notes                  TEXT, 
     is_active              BOOLEAN NOT NULL DEFAULT TRUE 
 ); 


